.callout[data-callout="important"] {
--ba-co-tint: color-mix(in srgb, #fffdf8 30%, transparent);
}
:where(.theme-dark) .callout[data-callout="important"] {
--ba-co-tint: color-mix(in srgb, #473231 30%, transparent);
}
.callout:is([data-callout="danger"], [data-callout="error"], [data-callout="failure"], [data-callout="fail"], [data-callout="missing"]) {
--ba-co-tint: color-mix(in srgb, var(--callout-color) 11%, transparent);
}
.callout:is([data-callout="important"], [data-callout="danger"], [data-callout="error"], [data-callout="failure"], [data-callout="fail"], [data-callout="missing"])::before {
--ba-co-lc: var(--callout-color);
}
.callout:is([data-callout="important"], [data-callout="danger"], [data-callout="error"], [data-callout="failure"], [data-callout="fail"], [data-callout="missing"])::after {
background: var(--ba-tag-grain) 0 0 / 256px 256px, var(--callout-color);
}
.callout-title {
font-family: var(--ba-font-display);
color: var(--callout-color);
letter-spacing: 0.02em;
align-items: center;
}
.callout:not(.is-collapsed) .callout-title {
padding-bottom: 6px;
margin-bottom: 4px;
background: linear-gradient(to right, color-mix(in srgb, var(--callout-color) 45%, transparent), transparent 85%) left bottom / 100% 1px no-repeat;
}
body:not(.ba-no-callout-latin) .callout[data-callout] .callout-title-inner::before {
content: var(--ba-latin, "");
margin-inline-end: 0.7em;
font-family: var(--ba-font-caps);
font-size: 0.8em;
font-weight: 600;
letter-spacing: 0.16em;
color: var(--ba-gold-deep);
vertical-align: 0.12em;
}
.callout-content > :first-child {
