.workspace-leaf-content[data-type="empty"] .empty-state-container {
max-height: none;
}
.theme-dark .workspace-leaf-content[data-type="empty"] .empty-state {
overflow-x: hidden;
}
.theme-dark .workspace-leaf-content[data-type="empty"] .empty-state-container {
position: relative;
isolation: isolate;
}
.theme-dark .workspace-leaf-content[data-type="empty"] .empty-state-container::after {
content: "";
position: absolute;
z-index: -1;
left: 50%;
top: calc(-1 * 150px);
width: 1100px;
height: 800px;
margin-left: calc(1100px / -2);
pointer-events: none;
background: url("data:image/webp;base64,") center / 100% 100% no-repeat;
}
.workspace-leaf-content[data-type="empty"] .empty-state-title {
font-family: var(--ba-font-display);
letter-spacing: 0.06em;
color: var(--ba-ink-2);
margin-top: 1.4em;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action-list {
gap: 10px;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action {
position: relative;
isolation: isolate;
overflow: visible;
height: 46px;
justify-content: flex-start;
padding: 0 63px;
border: 0;
border-radius: 0;
box-shadow: none;
background: none;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action:hover {
background: none;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action::before,
.workspace-leaf-content[data-type="empty"] .empty-state-action::after {
content: "";
position: absolute;
inset: 0;
pointer-events: none;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action::before {
z-index: -1;
background-color: var(--background-modifier-border);
-webkit-mask: var(--ba-u29) 0 0 / 100% 100% no-repeat;
mask: var(--ba-u29) 0 0 / 100% 100% no-repeat;
transition: background-color 0.15s;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action::after {
z-index: -2;
background-color: #e2cb98;
-webkit-mask: var(--ba-u30) 0 0 / 100% 100% no-repeat;
mask: var(--ba-u30) 0 0 / 100% 100% no-repeat;
opacity: 0;
transition: opacity 0.15s;
}
:where(.theme-dark) .workspace-leaf-content[data-type="empty"] .empty-state-action::after {
background-color: #952327;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action:hover::before {
background-color: #bf9f68;
}
:where(.theme-dark) .workspace-leaf-content[data-type="empty"] .empty-state-action:hover::before {
background-color: #661119;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action:hover::after {
opacity: 1;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action .text-button-label {
font-family: var(--ba-font-display);
font-size: 14.7px;
font-weight: 600;
letter-spacing: 0.02em;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action :is(.text-button-icon, .text-button-label) {
transition: color 0.15s;
}
.workspace-leaf-content[data-type="empty"] .empty-state-action:hover :is(.text-button-icon, .text-button-label) {
color: var(--ba-crimson);
}
.workspace-leaf-content[data-type="empty"] .empty-state-action .empty-state-hotkey {
margin-inline: 4px 0;
padding: 0;
background: none;
font-family: var(--ba-font-latin);
font-style: italic;
font-size: 14px;
